insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mt3_v1'
from (values
('117.321.c.1.A',3,'A junior leads the cast in a warm-up of breath work, vocal sirens and a dance isolation drill before a run-through. She is ___ a preparation routine.','["Creating", "Charging for", "Hiding", "Cancelling"]'::jsonb,0,'Level III students design warm-ups for the company.','original'),
('117.321.c.1.A',3,'Which element would a student leader add to a warm-up for a show with heavy tap choreography?','["Only a costume fitting", "Ankle and calf conditioning along with a vocal warm-up", "A lobby display", "A ticket count"]'::jsonb,1,'A warm-up fits the demands of the show.','original'),
('117.321.c.1.B',3,'A student blends ballet lines with tap rhythms in a transition between two songs. She is building skill in ___.','["Light board programming", "Set painting", "Movement across several dance genres", "Box office reports"]'::jsonb,2,'Musical theatre requires multiple dance genres.','original'),
('117.321.c.1.B',3,'A performer shows a character climbing a staircase that is not there, using only her body. She is using ___.','["Underscoring", "A cue sheet", "A rake", "Pantomime"]'::jsonb,3,'Pantomime implies objects that are absent.','original'),
('117.321.c.1.C',3,'A performer keeps the same emotional urgency while switching between a spoken scene, a sung verse and a dance break. She is developing ___.','["Acting technique that links song, dance and dialogue", "A cue list", "A marketing plan", "A budget"]'::jsonb,0,'Technique must carry through all three modes.','original'),
('117.321.c.1.C',3,'What is a useful way to prevent a song from feeling like a break in the story?','["Face away from the scene partner", "Treat the song as a moment of action that moves the character toward a goal", "Stand still and recite the notes", "Skip all emotion"]'::jsonb,1,'Songs are dramatic action.','original'),
('117.321.c.1.D',3,'A student demonstrates how to slate, hand a pianist clear sheet music, and perform a contrasting pair of songs. She is modeling ___.','["Press coverage", "Set strike", "Professional audition technique", "Tech rehearsal"]'::jsonb,2,'Modeling means showing correct practice.','original'),
('117.321.c.1.D',3,'Which audition choice shows good preparation?','["A song learned that morning", "Loose pages in no order", "A song without the music", "Songs marked with tempos, cuts and a clear key for the accompanist"]'::jsonb,3,'Organized music helps the panel and pianist.','original'),
('117.321.c.1.E',3,'A student charts the exposition, rising action, climax and resolution of a musical, marking where each song falls. She is ___ the dramatic structure.','["Analyzing", "Ignoring", "Costuming", "Selling"]'::jsonb,0,'Mapping songs on the arc is analysis.','original'),
('117.321.c.1.E',3,'In many musicals, the eleven o''clock number occurs late in the second act. What is its usual dramatic job?','["To begin the overture", "To deliver a high-energy or emotional peak before the resolution", "To introduce the cast", "To end the run"]'::jsonb,1,'Late big numbers sharpen the climax.','original'),
('117.321.c.1.F',3,'A student plays a role with a clear age, background, motivation and physical habits. She is performing a character with physical, intellectual and ___ dimensions.','["Legal", "Seasonal", "Emotional", "Financial"]'::jsonb,2,'The standard names these three dimensions.','original'),
('117.321.c.1.F',3,'Which choice best shows a character''s intellectual dimension in performance?','["The color of the costume", "Where the ticket was bought", "The theatre''s address", "How the character thinks, plans and speaks about ideas"]'::jsonb,3,'Intellect shows through thought and language.','original'),
('117.321.c.1.G',3,'A cast member listens to the choreographer, the composer''s notes and the stage manager''s calls, then adjusts her work. She is collaborating ___.','["With all artistic partners", "Only alone", "With nobody", "Against the director"]'::jsonb,0,'Collaboration crosses roles.','original'),
('117.321.c.1.G',3,'A conflict arises between the musical director and the choreographer over a tempo. What is the most professional step?','["Walk out", "Discuss it respectfully and reach a plan that serves the number", "Change the tempo secretly", "Announce it to the audience"]'::jsonb,1,'Resolve differences professionally.','original'),
('117.321.c.1.H',3,'A stage manager says to move ''stage left, upstage.'' The performer should move toward the performer''s ___ and away from the audience.','["Center, toward the pit", "Right side, toward the front", "Left side, toward the back", "Right side, toward the lobby"]'::jsonb,2,'Stage directions are from the performer''s view.','original'),
('117.321.c.1.H',3,'In musical theatre language, an ''overture'' is ___.','["A lighting plot", "A closing bow", "A costume change", "An orchestral piece that opens the show with themes from the score"]'::jsonb,3,'Overtures preview the music.','original'),
('117.321.c.2.A',3,'A student leader reminds the ensemble to rest the voice between long rehearsals and warm up the body before dance calls. She is applying ___.','["Safety measures for vocal and physical health", "Set design", "A casting list", "A marketing tool"]'::jsonb,0,'Safety covers voice and movement.','original'),
('117.321.c.2.A',3,'If a dancer feels a sharp pain in her ankle during a number, she should ___.','["Dance harder", "Stop and report it right away", "Hide it", "Finish the show without telling anyone"]'::jsonb,1,'Reporting prevents worse injury.','original'),
('117.321.c.2.B',3,'A student reviews her creative choices and her ensemble''s choices after a run, noting what worked and what to try next. She is ___ creativity.','["Cancelling", "Avoiding", "Appraising", "Hiding"]'::jsonb,2,'Appraising means assessing value.','original'),
('117.321.c.2.B',3,'An ensemble that welcomes new ideas and tests them in rehearsal is practicing ___.','["Avoidance", "Disorder", "Rigid copying", "Collaborative creativity"]'::jsonb,3,'Open testing builds shared work.','original'),
('117.321.c.2.C',3,'An actor chooses a walk, a vocal color and a style of dancing that all suit one character, then keeps them steady through the show. She is ___ a believable character.','["Creating and sustaining", "Costing", "Selling", "Dismissing"]'::jsonb,0,'Consistency makes characters believable.','original'),
('117.321.c.2.C',3,'Which combination helps a performer build a believable character across a musical?','["Mimicking another actor line by line", "Acting choices, vocal choices and movement choices that agree", "No choices", "Random choices every night"]'::jsonb,1,'All modes should align.','original'),
('117.321.c.2.D',3,'A student demonstrates how breath support, resonance and diction improve a ballad, and coaches a classmate. She is modeling ___.','["Box office sales", "Fly rail operation", "Correct vocal production", "Prop storage"]'::jsonb,2,'Modeling shows correct technique.','original'),
('117.321.c.2.D',3,'Which habit supports healthy belting in a musical?','["Holding the breath", "Tensing the neck", "Pushing from the throat alone", "Strong breath support with a relaxed jaw and throat"]'::jsonb,3,'Support reduces strain.','original'),
('117.321.c.2.E',3,'A student reads the lyrics of a duet as a conversation between two characters, marking what each one wants. She is analyzing the song as a ___.','["Dialogue", "Warm-up", "Program note", "Costume plot"]'::jsonb,0,'A duet can be read as dialogue.','original'),
('117.321.c.2.E',3,'Reading a song''s lyrics as an ensemble scene helps performers decide ___.','["How tall the set is", "Who is speaking, who is listening and how the group reacts", "Where to park", "Which seats to sell"]'::jsonb,1,'Lyric analysis shapes interpretation.','original'),
('117.321.c.2.F',3,'Three students write a short scene and lyric, set it with simple movement and teach it to the class. They are ___ material.','["Cancelling", "Erasing", "Collaboratively producing", "Selling"]'::jsonb,2,'Producing includes writing, staging and teaching.','original'),
('117.321.c.2.F',3,'Which is a strong first step when a group creates a short musical scene?','["Hire an usher", "Sew the curtain", "Print the tickets", "Agree on the characters, the conflict and the moment of song"]'::jsonb,3,'Story first.','original'),
('117.321.c.3.A',3,'A student leader demonstrates how to set a microphone, check cables and tape down a cord before a number. She is modeling ___.','["Safe and effective use of technical elements", "Poor planning", "Ignoring rules", "Skipping rehearsal"]'::jsonb,0,'Modeling demonstrates correct use.','original'),
('117.321.c.3.A',3,'Why should a performer know where the fly rail and trap door are before a number that uses them?','["To shorten the song", "To avoid injury and keep the scene change safe", "To sell more tickets", "To rewrite the score"]'::jsonb,1,'Awareness prevents accidents.','original'),
('117.321.c.3.B',3,'A student drafts a rehearsal plan with a blocking chart, a dance timeline and a lighting cue list. She is ___ a production plan.','["Selling", "Tearing down", "Creating", "Erasing"]'::jsonb,2,'Plans include rehearsal and technical items.','original'),
('117.321.c.3.B',3,'Which item belongs in a technical design plan for a musical?','["A bus schedule", "A weather forecast", "A grocery list", "A list of sound cues, scenery changes and lighting looks"]'::jsonb,3,'Technical plans organize cues.','original'),
('117.321.c.3.C',3,'A student stage manager keeps calm during a mistake and finds a quick fix to keep the number going. She shows ___ as a leader.','["Responsibility and creative problem solving", "Absence", "Blame", "Panic"]'::jsonb,0,'Leaders solve problems.','original'),
('117.321.c.3.C',3,'When a student leads a department like costumes or sound, she should ___.','["Do every job alone", "Set goals, share tasks and check progress with her team", "Ignore feedback", "Avoid deadlines"]'::jsonb,1,'Leaders organize people.','original'),
('117.321.c.3.D',3,'A student can serve as actor, director, choreographer, designer or technician in a class production. Doing so builds ___.','["Isolation", "Delays", "Understanding of how each role supports the show", "Confusion"]'::jsonb,2,'Roles are interconnected.','original'),
('117.321.c.3.D',3,'A student acts as assistant director during a rehearsal. What is a key duty?','["Close the theatre", "Drive the cast", "Sell snacks", "Help keep the schedule and give notes from the director"]'::jsonb,3,'Assistants support the director.','original'),
('117.321.c.4.A',3,'A student explains how minstrelsy, vaudeville and operetta shaped early musicals, and how immigration and jazz changed later ones. She is ___ influences.','["Articulating historical and cultural", "Hiding", "Ignoring", "Cancelling"]'::jsonb,0,'Articulate means to explain clearly.','original'),
('117.321.c.4.A',3,'Which describes a cultural influence on musical theatre?','["The width of the stage", "The rise of jazz and swing music in popular culture", "The cost of tickets only", "The color of the walls"]'::jsonb,1,'Popular music shaped scores.','original'),
('117.321.c.4.B',3,'A student traces a line from operetta to the Golden Age to concept musicals. She is examining the ___ of an American art form.','["Price list", "Scenery inventory", "Historical development", "Parking"]'::jsonb,2,'Tracing eras shows development.','original'),
('117.321.c.4.B',3,'Which statement is accurate about the American musical?','["It has never changed", "It began with television", "It is unrelated to history", "It grew from a blend of European and American stage traditions"]'::jsonb,3,'Traditions merged over time.','original'),
('117.321.c.4.C',3,'A student studies a new composer who blends pop, folk and classical styles in a score, then tries a similar approach in a short song. She is ___ with contemporary forms.','["Experimenting", "Closing", "Retiring", "Banning"]'::jsonb,0,'Experiment means to try.','original'),
('117.321.c.4.C',3,'What is a hallmark of many contemporary musicals?','["Avoiding music", "Mixing styles such as pop, rock and hip-hop with storytelling", "Using only silent film", "Rejecting plot"]'::jsonb,1,'Contemporary scores borrow widely.','original'),
('117.321.c.4.D',3,'A student argues that a particular musical shows the worries and hopes of its era using evidence from its songs and story. She is ___ musical theatre as a reflection of life.','["Copying", "Burying", "Defending", "Deleting"]'::jsonb,2,'Defend means to support with reasoning.','original'),
('117.321.c.4.D',3,'Which evidence best supports the claim that a musical reflects its culture?','["Its ticket price only", "Its poster color", "The theatre address", "Specific lyrics, settings and costumes tied to a time and place"]'::jsonb,3,'Details give evidence.','original'),
('117.321.c.4.E',3,'A film adaptation of a stage musical uses close-ups and location shots. A student explains how this reflects ___.','["The influence of film on musical theatre forms", "A change in the lobby", "A change in the weather", "A change in the school bus"]'::jsonb,0,'Forms influence each other.','original'),
('117.321.c.4.E',3,'Which shows how television has changed the reach of musical theatre?','["TV bans dance", "Televised live musicals bring stage shows to many homes", "TV removes all music", "TV ends theatre"]'::jsonb,1,'TV broadens audiences.','original'),
('117.321.c.5.A',3,'A student leader teaches younger students how to behave at a school musical, a community concert and a touring show. She is ___ appropriate audience behavior.','["Ignoring", "Selling", "Modeling", "Breaking"]'::jsonb,2,'Modeling shows by example.','original'),
('117.321.c.5.A',3,'Which behavior fits a formal musical theatre performance?','["Chatting with neighbors", "Walking up the aisle mid-song", "Recording the show", "Silencing devices and staying until the curtain call"]'::jsonb,3,'Respect the performers.','original'),
('117.321.c.5.B',3,'A student gives a short speech arguing that musical theatre is a creative art form and reflects on her own growth. She is ___ it.','["Defending", "Skipping", "Rejecting", "Hiding"]'::jsonb,0,'Defend means to argue support.','original'),
('117.321.c.5.B',3,'Which statement best defends musical theatre as art?','["It has no purpose", "It expresses ideas and emotion through music, words and movement", "It is only for tourists", "It is only a business"]'::jsonb,1,'Art expresses meaning.','original'),
('117.321.c.5.C',3,'A student explains how the book, score, choreography, design and orchestra depend on each other to tell a story. She is evaluating ___.','["The lobby music", "The seat layout", "The interdependence of elements", "The ticket line"]'::jsonb,2,'Elements work together.','original'),
('117.321.c.5.C',3,'If the choreography does not match the music''s mood, which other element is also affected?','["The seat numbers", "The parking lot", "The ticket price", "The story''s emotional impact"]'::jsonb,3,'Misalignment weakens the story.','original'),
('117.321.c.5.D',3,'After a showcase, a student writes to a classmate: ''Your phrasing was warm, and the spin in the bridge was strong; try clearer consonants in the verse.'' This is ___.','["Constructive criticism", "An insult", "A rumor", "A sales pitch"]'::jsonb,0,'Balanced and specific.','original'),
('117.321.c.5.D',3,'What is a good approach when asking a peer for feedback?','["Refuse to listen", "Ask what to keep and what to change", "Demand praise only", "Argue every point"]'::jsonb,1,'Seek useful information.','original'),
('117.321.c.5.E',3,'A student discusses a film musical using words like ensemble, reprise, book and choreography. She is using ___.','["Slang only", "Vague terms", "Precise musical theatre vocabulary", "Silence"]'::jsonb,2,'Precise vocabulary clarifies discussion.','original'),
('117.321.c.5.E',3,'A ''reprise'' in a musical is ___.','["A new overture", "A curtain call", "An intermission", "A repeated song or musical theme that returns later with new meaning"]'::jsonb,3,'Reprises echo earlier music.','original'),
('117.321.c.5.F',3,'A student shadows a stage manager for a week to learn what the job involves. She is ___ with a career opportunity.','["Experimenting", "Selling", "Banning", "Retiring"]'::jsonb,0,'Shadowing is a way to try a career.','original'),
('117.321.c.5.F',3,'Which is a possible career in musical film?','["Welder", "Music supervisor", "Pilot", "Surveyor"]'::jsonb,1,'Music supervisors work in film.','original'),
('117.321.c.5.G',3,'Teamwork, memorization and public speaking learned in musical theatre help a student in ___.','["No future setting", "Only the next show", "Higher education and careers outside theatre", "Only a talent show"]'::jsonb,2,'Skills transfer.','original'),
('117.321.c.5.G',3,'A student says her rehearsal discipline will help in nursing school. She is ___ theatre to higher education.','["Avoiding", "Ending", "Burying", "Relating"]'::jsonb,3,'She links skills to her future path.','original'),
('117.321.c.5.H',3,'A student builds a clear online portfolio of her performances with captions and dates. She is ___ information with technology.','["Documenting and presenting", "Deleting", "Ignoring", "Hiding"]'::jsonb,0,'Portfolios document growth.','original'),
('117.321.c.5.H',3,'Which feature makes a digital performance portfolio coherent?','["Random order", "Organized sections with labels and brief reflections", "Blank pages", "Mixed unlabeled files"]'::jsonb,1,'Order and labels help viewers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
